@startuml

class Person {
  + name : string
  + email : string
}

class Student extends Person {
}

class Tutor extends Person {
  + bankAccount : string
}

class TutoringOffer {
  + subject : string
  + expertiseLevel : string
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + requestedLevel : string
  + suggestedDate : date
  + suggestedTime : time
}

class TutoringSession {
  + sessionDate : date
  + sessionTime : time
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringRequest : receives
Tutor "1" -- "*" TutoringSession : conducts
Student "1" -- "*" TutoringRequest : makes
Student "1" -- "*" TutoringSession : attends
Student "1" -- "0..1" Payment : pays for
TutoringSession "1" -- "0..1" TutoringSession : follow-up
TutoringSession "1" -- "0..1" Payment : results in

@enduml

